def check_n_fixed(n_val):
    K = n_val + 1
    y = [None] * K
    y[K-1] = 1
    forbidden_pairs = []
    for n in range(32, K):
        d_min = max(1024, K-2*n)
        d_max = K-n-1
        for d in range(d_min, d_max + 1):
            forbidden_pairs.append((n, n + d))
    changed = True
    while changed:
        changed = False
        for n in range(32, K):
            for d in range(1024, K - 2*n):
                idx_2nd, idx_nd, idx_n = 2*n + d, n + d, n
                if y[idx_2nd] == 1:
                    if y[idx_nd] == 0:
                        if y[idx_n] == 0: return False
                        if y[idx_n] != 1: y[idx_n] = 1; changed = True
                    elif y[idx_n] == 0:
                        if y[idx_nd] == 0: return False
                        if y[idx_nd] != 1: y[idx_nd] = 1; changed = True
                if y[idx_nd] == 1 and y[idx_n] == 1:
                    if y[idx_2nd] == 0: return False
                    if y[idx_2nd] != 1: y[idx_2nd] = 1; changed = True
                if y[idx_2nd] == 0:
                    if y[idx_nd] == 1:
                        if y[idx_n] == 1: return False
                        if y[idx_n] != 0: y[idx_n] = 0; changed = True
                    elif y[idx_n] == 1:
                        if y[idx_nd] == 1: return False
                        if y[idx_nd] != 0: y[idx_nd] = 0; changed = True
                if y[idx_nd] == 0 and y[idx_n] == 0:
                    if y[idx_2nd] == 1: return False
                    if y[idx_2nd] != 0: y[idx_2nd] = 0; changed = True
        for i, j in forbidden_pairs:
            if y[i] == 1:
                if y[j] == 1: return False
                if y[j] != 0: y[j] = 0; changed = True
            if y[j] == 1:
                if y[i] == 1: return False
                if y[i] != 0: y[i] = 0; changed = True
    return True

